/// A two-dimensional array: lower and upper row, lower and upper column, the values row by row.
impl<T: Emit> Emit for Array2<T> {
    fn emit(&self, g: &mut Got) {
        g.i(1);
        g.l(self.rows());
        g.i(1);
        g.l(self.cols());
        for x in self.as_slice() {
            x.emit(g);
        }
    }
}
